function validate([paint]) {
  if (!Array.isArray(paint) || paint.length < 1 || paint.length > 100000) return 'paint needs 1 to 10^5 days.';
  for (const day of paint) {
    if (!Array.isArray(day) || day.length !== 2) return 'Each day is a pair [start, end].';
    const [start, end] = day;
    if (!Number.isInteger(start) || !Number.isInteger(end)) return 'start and end are integers.';
    if (start < 0 || end > 50000 || start >= end) return 'Each day needs 0 <= start < end <= 5 * 10^4.';
  }
  return null;
}

