function amountPainted(paint) {
  let size = 1;
  for (const [, end] of paint) {
    size = Math.max(size, end);
  }
  const painted = new Array(4 * size).fill(0);

  function paintRange(node, left, right, start, end) {
    if (end <= left || right <= start) {
      return 0;
    }
    if (painted[node] === right - left) {
      return 0;
    }
    if (start <= left && right <= end) {
      const added = right - left - painted[node];
      painted[node] = right - left;
      return added;
    }
    const mid = Math.floor((left + right) / 2);
    const fromLeft = paintRange(2 * node, left, mid, start, end);
    const fromRight = paintRange(2 * node + 1, mid, right, start, end);
    painted[node] = painted[2 * node] + painted[2 * node + 1];
    return fromLeft + fromRight;
  }

  const worklog = [];
  for (const [start, end] of paint) {
    worklog.push(paintRange(1, 0, size, start, end));
  }
  return worklog;
}

