function amountPainted(paint) {
  const wall = new Set();
  return paint.map(([start, end]) => {
    let fresh = 0;
    for (let x = start; x < end; x++) {
      if (!wall.has(x)) {
        wall.add(x);
        fresh++;
      }
    }
    return fresh;
  });
}

