function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const paint = [];
  if (size === 'small') {
    const n = int(1, 7);
    const limit = int(1, 16);
    for (let i = 0; i < n; i++) {
      if (paint.length > 0 && rand() < 0.2) { paint.push([...paint[int(0, paint.length - 1)]]); continue; }
      const start = int(0, limit - 1);
      paint.push([start, int(start + 1, limit)]);
    }
    return [paint];
  }
  const limit = 50000;
  for (let i = 0; i < 2000; i++) {
    const pick = rand();
    const length = pick < 0.5 ? int(1, 60) : pick < 0.9 ? int(1, 3000) : int(1, limit);
    const start = int(0, limit - length);
    paint.push([start, start + length]);
  }
  return [paint];
}
